pub struct Subject { pub id: String, pub roles: Vec<String> }   // immutable descriptor

// middleware builds it once; the extractor makes absence a hard error
impl<S: Send + Sync> FromRequestParts<S> for Subject {
    type Rejection = StatusCode;
    async fn from_request_parts(parts: &mut Parts, _: &S) -> Result<Self, Self::Rejection> {
        parts.extensions.get::<Subject>().cloned().ok_or(StatusCode::UNAUTHORIZED)
    }
}

async fn report(subject: Subject) -> String { format!("hello {}", subject.id) }

